var K = window.__CK || (window.__CK = {});
K.N = 3;
K.X = [16.7,50,83.3];
K.Y = { top: 13, mid: 38, bot: 67 };
K.CODE = ["flutter analyze","flutter test","pr-review-mechanical"];
K.SLOT = "not run";
K.PANEL = {"sub":"pull request","chip":"open","name":"🔀  feat: cancel order and refund"};

K.scene = function(id){ MSD.cls('.ck-sc', 'on', false); MSD.cls('#ck-sc-' + id, 'on', true); };
K.strip = function(label, text, tone){
  MSD.cls('#ck-strip', 'bad', tone === 'bad'); MSD.cls('#ck-strip', 'good', tone === 'good');
  MSD.q('#ck-strip-l').textContent = label; MSD.q('#ck-strip-t').textContent = text;
};
K.tones = function(sel, tone, list){ list.forEach(function(c){ MSD.cls(sel, c, tone === c); }); };
K.chip = function(sel, text, tone){
  var v = MSD.q(sel); v.textContent = text;
  ['ok','bad','warn'].forEach(function(c){ v.classList.toggle(c, tone === c); });
};

K.card = function(i, text, tone){ MSD.q('#ck-card-t-' + i).textContent = text; K.tones('#ck-card-' + i, tone, ['live','bad','good','warn']); };
K.cards = function(text, tone){ for(var i = 1; i <= K.N; i++) K.card(i, text, tone); };
K.code = function(i, text){ MSD.q('#ck-code-' + i).textContent = text; };

K.mid = function(i, on, title, chip, tone, chipTone){
  MSD.cls('#ck-mid-' + i, 'slot', !on);
  K.tones('#ck-mid-' + i, tone, ['live','ok','bad','warn']);
  MSD.q('#ck-mid-t-' + i).textContent = on ? title : K.SLOT;
  K.chip('#ck-mid-v-' + i, chip || '—', chipTone);
};
K.mids = function(on, title, chip, tone, chipTone){ for(var i = 1; i <= K.N; i++) K.mid(i, on, title, chip, tone, chipTone); };

K.ar = function(row, i, tone){ K.tones('#ck-a' + row + '-' + i, tone, ['live','bad','ok','dim']); };
K.ars = function(row, tone){ for(var i = 1; i <= K.N; i++) K.ar(row, i, tone); };

K.panel = function(tone, chip, chipTone, sub, name){
  K.tones('#ck-panel', tone, ['ok','bad','warn']);
  MSD.q('#ck-panel-n').textContent = name || K.PANEL.name;
  K.chip('#ck-panel-v', chip || K.PANEL.chip, chipTone);
  MSD.q('#ck-panel-s').textContent = sub || K.PANEL.sub;
};
K.row = function(i, state, name, value){
  K.tones('#ck-r-' + i, state, ['empty','gone','bad','warn','ok']);
  MSD.q('#ck-r-n-' + i).textContent = name || '—';
  MSD.q('#ck-r-v-' + i).textContent = value || '';
};

// Something travelling between rows in one column; the bottom panel is centred.
K.go = function(col, from, to, n){
  var fx = from === 'bot' ? 50 : K.X[col], tx = to === 'bot' ? 50 : K.X[col];
  MSD.particles('#ck-scene', { from:{ x:fx, y:K.Y[from] }, to:{ x:tx, y:K.Y[to] }, count:n || 5, duration:650, spread:18 });
};

K.reset = function(){
  K.scene('world');
  for(var i = 1; i <= K.N; i++){ K.card(i, 'ready', ''); K.code(i, K.CODE[i - 1]); K.mid(i, false); K.ar(1, i, ''); K.ar(2, i, ''); }
  for(var r = 1; r <= 4; r++) K.row(r, 'empty');
  K.panel('', K.PANEL.chip, '', K.PANEL.sub);
};

K.reset();
MSD.after(500, function(){ K.row(1, 'warn', 'CancelOrder use case', 'new'); MSD.sfx.pop(); });
MSD.after(1000, function(){ K.row(2, 'warn', 'Cancel button on the order screen', 'new'); });
MSD.after(1500, function(){ K.row(3, 'warn', '3 tests', 'new'); });
MSD.after(2600, function(){ K.strip('REVIEW', 'Four gates stand between it and main.', ''); });

